mapper.select:
select

from survey_channel_cost
where  1 = 1 and delete_flag = 0

  and survey_org_id = #{surveyOrgId,jdbcType=BIGINT}


  and survey_user_id = #{surveyUserId,jdbcType=BIGINT}

 order by id desc limit 1

select

from survey_channel_cost c
where 1 = 1 and c.delete_flag = 0

    and c.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


  and find_in_set(c.state,#{states,jdbcType=VARCHAR})


  and c.survey_user_name like CONCAT(CONCAT('%',#{orgUserName,jdbcType=VARCHAR}), '%')


  and c.is_pro_pay = #{isProPay,jdbcType=INTEGER}


  AND date_format(c.operation_time,'%Y-%m-%d') >= #{startTime,jdbcType=VARCHAR}


  AND date_format(c.operation_time,'%Y-%m-%d') <= #{endTime,jdbcType=VARCHAR}

order by c.id desc

  limit #{pageIndex}, #{pageSize}

  select count(1) from survey_channel_cost c where 1 = 1 and c.delete_flag = 0

and c.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


and find_in_set(c.state,#{states,jdbcType=VARCHAR})


and c.survey_user_name like CONCAT(CONCAT('%',#{orgUserName,jdbcType=VARCHAR}), '%')


and c.is_pro_pay = #{isProPay,jdbcType=INTEGER}


AND date_format(c.operation_time,'%Y-%m-%d') >= #{startTime,jdbcType=VARCHAR}


AND date_format(c.operation_time,'%Y-%m-%d') <= #{endTime,jdbcType=VARCHAR}
